/**Stores all data related to sessions hosting */
const postnextSessions = {};
const keepSessions = {};
const keepData = {};

const rateLimitation = {
	/** Tracks request count per session and enforces rate limits.
	 * If requests exceed 'max' within 'timeTo' ms, further actions are blocked.
	 * @param {string} sessionId - Unique identifier for the client/session.
	 * @param {string} where - Data namespace or socket label storing limits.
	 * @param {number} max - Max allowed attempts within the time window (default: 10).
	 * @param {number} timeTo - Time window in milliseconds before reset (default: 60000).
	 * @returns {Promise<boolean>} - True if under the rate limit, false if exceeded. */
	checkRateLimit: async (sessionId, where, max = 10, timeTo = 60000) => {
		try {
			const currentTime = Date.now();
			if (!keepData[where].rateLimits[sessionId]) {
				keepData[where].rateLimits[sessionId] = { count: 1, timestamp: currentTime };
			} else {
				const rateEntry = keepData[where].rateLimits[sessionId];
				const timeElapsed = currentTime - rateEntry.timestamp;
				if (timeElapsed > timeTo) {
					rateEntry.count = 1;
					rateEntry.timestamp = currentTime;
				} else rateEntry.count += 1;
			}
			return keepData[where].rateLimits[sessionId].count <= max;
		} catch (error) {
			console.error("Rate limit error:", error);
			return false;
		}
	},

	/** Initializes a scoped in-memory store for session/socket context.
	 * @param {string} where - Top-level namespace for storage.
	 * @param {string} name - Optional nested name if sub-store is needed. */
	createDatabase: (where, name) => {
		const defaultSchema = {
			files: {},
			timeout: {},
			streams: [],
			rateLimits: {},
			senderStream: {},
		};
		if (!keepData[where]) keepData[where] = defaultSchema;
		else if (!keepData[where][name]) keepData[where][name] = {};
	},
};

const createdEvents = {
	/** Manages timed events per session with flexible control.
	 * Used for creating timestamps, checking expiry, or clearing state.
	 * @param {string} sessionId - Identifier for the client/session.
	 * @param {string} where - Namespace where timeout info is stored.
	 * @param {string} action - Can be 'create', 'check', or 'clear'.
	 * @param {number} timeTo - Duration in ms before timeout expires (default: 5 min).
	 * @returns {boolean|undefined} - Returns true if expired on 'check', otherwise undefined. */
	timed: (sessionId, where, action, timeTo = 5 * 60000) => {
		const now = Date.now();
		if (action === 'create' && !keepData[where]?.timeout[sessionId]) {
			keepData[where] = { timeout: sessionId = { timestamp: now } };
		}
		if (keepData[where] && (action === 'check' || action === 'create') && keepData[where]?.timeout[sessionId]?.timestamp) {
			const timeElapsed = now - keepData[where].timeout[sessionId].timestamp;
			if (timeElapsed > timeTo) {
				if (!checKeepSession(sessionId)) delete keepData[where].timeout[sessionId];
				return true;
			}
			return false;
		} else if (action === 'clear' && keepData[where]?.timeout[sessionId]) delete keepData[where].timeout[sessionId];
		else return false;
	},
};

/** getRandomPatternClass
 * Returns one random CSS pattern class from a predefined list.
 * @returns {string}
 *	A class name string such as "pattern-3". */
function getRandomPatternClass() {
	const classes = [
		"pattern-1", "pattern-2", "pattern-3", "pattern-4", "pattern-5",
		"pattern-6", "pattern-7", "pattern-8", "pattern-9", "pattern-10",
		"pattern-11", "pattern-12", "pattern-13", "pattern-14", "pattern-15"
	];
	const randomIndex = Math.floor(Math.random() * classes.length);
	return classes[randomIndex] || '';
}

